			function doCtpvList() {
			    
			    //조회 서브미션 호출
			    util.Submit.send(app, "subCtpvList", function(pbSuccess) {
			        if (pbSuccess) {
			            util.Msg.notify(app, "INF-M001");
			        }
			            
			        util.Control.redraw(app, "grpData");
			        
			        var rowCount = util.DataSet.getRowCount(app, "dsCtpvList");
			        
			        for(var i = 0; i < rowCount; i++){
			            var ctpvCd = util.DataSet.getValue(app, "dsCtpvList", i, "CTPV_CD");
			            var ctpvNm = util.DataSet.getValue(app, "dsCtpvList", i, "CTPV_NM");
			            var ctpvCnt = util.DataSet.getValue(app, "dsCtpvList", i, "CTPV_CNT");
			            /** @type cpr.controls.Output */
			            var optRgn = app.lookup("opt" + (i+1).toString());
			            
			            optRgn.userAttr({
			            	CTPV_CD : ctpvCd,
			            	CTPV_NM : ctpvNm,
			                CTPV_CNT : ctpvCnt,
			            });
			             
			            optRgn.displayExp =  "'" + optRgn.userAttr("CTPV_NM") + " '" + " + sstr('" + optRgn.userAttr("CTPV_CNT") + "', \"sub-title\") + '개소'";
			                
			        }

			        for(var i = 1; i < rowCount; i++){
			            var ctpvCnt = util.DataSet.getValue(app, "dsCtpvList", i, "CTPV_CNT");
			            /** @type cpr.controls.Output */
			            var optImg = app.lookup("opt" + (i + 101).toString());
			            
			            optImg.value =  ctpvCnt;
			        }

			        //전국 count
			        var ctpvCnt = util.DataSet.getValue(app, "dsCtpvList", 0, "CTPV_CNT");
			        var vcOptImgMainTit = app.lookup("optImgMainTitle");
			        vcOptImgMainTit.value = ctpvCnt;

			        doList();
			            
			    });
			}

